import bleach


def clean_html(text):
    """Sanitize HTML from emails, allowing only basic formatting tags."""
    allowed_tags = {
        'b', 'i', 'em', 'strong', 'p', 'br', 'a', 'ul', 'ol', 'li', 'blockquote'
    }
    allowed_attributes = {'a': ['href', 'title']}
    return bleach.clean(text, tags=allowed_tags, attributes=allowed_attributes, strip=True)
